-- ─────────────────────────────────────────────────────────────────────────────
-- 146, What each ward was called before the 1 July 2025 merger
--
-- vn_wards (003) holds only today's units: 3,321 wards in 34 provinces, no
-- districts. People still write the old names ("Phường Bến Nghé, Quận 1"), in
-- posts and in search prompts, and those matched nothing. This table maps
-- every former ward, with its former district and province, to the ward(s) it
-- is part of now, so an old name can be read as today's ward.
--
-- One row per (former ward, current ward): 471 former wards were split between
-- two to five current wards and so have several rows; all count equally. Five
-- island districts became special zones as a whole and have no former ward
-- name (former_name NULL). Rows join vn_wards by its code; today's names stay
-- vn_wards' own.
--
-- Source: ankapong.com/sap-nhap/tai-danh-sach (all provinces, CSV), read
-- 2026-11-15. Its code for Xã Ba Chẽ (Quảng Ninh) was 06970; vn_wards has
-- 06978, used here.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS vn_ward_former_names (
  id              UUID  PRIMARY KEY DEFAULT gen_random_uuid(),
  former_name     TEXT,                       -- 'Phường Bến Nghé'
  former_district TEXT  NOT NULL,             -- 'Quận 1'
  former_province TEXT  NOT NULL,             -- 'Thành phố Hồ Chí Minh'
  ward_id         UUID  NOT NULL REFERENCES vn_wards (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_ward_former_names
  ON vn_ward_former_names (COALESCE(former_name, ''), former_district, former_province, ward_id);
CREATE INDEX IF NOT EXISTS idx_ward_former_names_ward ON vn_ward_former_names (ward_id);

